// 선택된 카드 하이라이트
scwin.highlightSelectedCard = function(selectedCardId) {
    try {
        var container = $p.getComponentById("repo_cards_container");
        if (container) {
            var children = container.getChildren();
            for (var i = 0; i < children.length; i++) {
                var card = children[i];
                if (card.getId() === selectedCardId) {
                    // 선택된 카드 스타일
                    card.setStyle("border-color: #007bff; box-shadow: 0 4px 16px rgba(0, 123, 255, 0.15);");
                } else {
                    // 일반 카드 스타일
                    card.setStyle("border-color: #e9ecef; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);");
                }
            }
        }
    } catch (e) {
        console.error("카드 하이라이트 실패:", e);
    }
};

