// 날짜 포맷 함수
scwin.formatDate = function(dateString) {
    if (!dateString) return "";

    try {
        var date = new Date(dateString);
        var now = new Date();
        var diff = now - date;
        var days = Math.floor(diff / (1000 * 60 * 60 * 24));

        if (days === 0) {
            return "오늘";
        } else if (days === 1) {
            return "어제";
        } else if (days < 7) {
            return days + "일 전";
        } else if (days < 30) {
            return Math.floor(days / 7) + "주 전";
        } else if (days < 365) {
            return Math.floor(days / 30) + "개월 전";
        } else {
            return Math.floor(days / 365) + "년 전";
        }
    } catch (e) {
        return dateString.substring(0, 10); // YYYY-MM-DD 형태로 표시
    }
};

// 에러 메시지 추출
scwin.getErrorMessage = function (error) {
    try {
        if (error.responseJSON && error.responseJSON.message) {
            return error.responseJSON.message;
        }
        if (error.responseText) {
            try {
                var parsed = JSON.parse(error.responseText);
                if (parsed.message) return parsed.message;
                if (parsed.error) return parsed.error;
            } catch (e) {
                return error.responseText;
            }
        }
        if (error.status) {
            switch (error.status) {
                case 401:
                    return "인증이 필요합니다. 로그인 후 다시 시도해주세요.";
                case 403:
                    return "권한이 없습니다. 액세스 토큰을 확인해주세요.";
                case 404:
                    return "요청한 리소스를 찾을 수 없습니다.";
                case 422:
                    return "입력 데이터가 올바르지 않습니다.";
                case 500:
                    return "서버 오류가 발생했습니다.";
                default:
                    return "HTTP " + error.status + " 오류가 발생했습니다.";
            }
        }
        return error.message || "알 수 없는 오류가 발생했습니다.";
    } catch (e) {
        console.error("에러 메시지 추출 실패:", e);
        return "오류 정보를 확인할 수 없습니다.";
    }
};

// 히스토리 추가
scwin.addToHistory = function (action, repoName, branchName, result) {
    try {
        dlt_repo_history.insertRow(0);
        dlt_repo_history.setCellData(0, "action", action);
        dlt_repo_history.setCellData(0, "repoName", repoName || "");
        dlt_repo_history.setCellData(0, "branchName", branchName || "");
        dlt_repo_history.setCellData(0, "timestamp", new Date().toLocaleString());
        dlt_repo_history.setCellData(0, "result", result);

        // 최대 50개 히스토리 유지
        while (dlt_repo_history.getTotalRow() > 50) {
            dlt_repo_history.deleteRow(dlt_repo_history.getTotalRow() - 1);
        }

        console.log("히스토리 추가:", action, repoName, branchName, result);
    } catch (e) {
        console.error("히스토리 추가 실패:", e);
    }
};

